create table if not exists public.routine_bundle_steps (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, bundle_id uuid not null, routine_id uuid not null, child_title text not null, child_order integer not null default 1 check (child_order > 0), active boolean not null default true, source text not null default 'me_plus', learned_from_external_task_id text, learned_from_parent_external_task_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,bundle_id,routine_id), foreign key(bundle_id,user_id) references public.routine_bundles(id,user_id) on delete cascade, foreign key(routine_id,user_id) references public.routines(id,user_id) on delete cascade); create unique index if not exists routine_bundle_steps_title_uidx on public.routine_bundle_steps(user_id,bundle_id,lower(child_title)) where active;
